import React, { useState } from 'react';
import {
  Box,
  Paper,
  Typography,
  TextField,
  Button,
  Grid,
  Container,
  Alert,
  Snackbar,
  Table,
  TableBody,
  TableCell,
  TableContainer,
  TableHead,
  TableRow
} from '@mui/material';
import axios from 'axios';

function CostCalculator() {
  const [formData, setFormData] = useState({
    scale: {
      consumers_per_tenant: 3,
      total_tenants: 5000,
      endpoints_per_tenant: 10000
    },
    cloud_provider: 'aws'
  });

  const [costBreakdown, setCostBreakdown] = useState(null);
  const [notification, setNotification] = useState({
    open: false,
    message: '',
    severity: 'success'
  });

  const handleInputChange = (field, value) => {
    setFormData(prev => ({
      ...prev,
      scale: {
        ...prev.scale,
        [field]: parseInt(value) || 0
      }
    }));
  };

  const calculateCosts = async () => {
    try {
      const response = await axios.post('http://localhost:8000/calculate-cost', formData);
      setCostBreakdown(response.data);
      setNotification({
        open: true,
        message: 'Cost calculation successful!',
        severity: 'success'
      });
    } catch (error) {
      setNotification({
        open: true,
        message: 'Error calculating costs: ' + (error.response?.data?.detail || error.message),
        severity: 'error'
      });
    }
  };

  const handleCloseNotification = () => {
    setNotification({ ...notification, open: false });
  };

  const formatCurrency = (value) => {
    return `$${value.toFixed(2)}`;
  };

  return (
    <Container maxWidth="lg">
      <Paper elevation={3} sx={{ p: 3, mt: 3 }}>
        <Typography variant="h4" gutterBottom>
          PxGrid Cloud Cost Calculator
        </Typography>

        <Box sx={{ mb: 4 }}>
          <Typography variant="h6" gutterBottom>
            Scale Parameters
          </Typography>

          <TableContainer component={Paper} sx={{ mb: 3 }}>
            <Table>
              <TableHead>
                <TableRow>
                  <TableCell>S.No</TableCell>
                  <TableCell>Scale Parameters</TableCell>
                  <TableCell>Count</TableCell>
                </TableRow>
              </TableHead>
              <TableBody>
                <TableRow>
                  <TableCell>1</TableCell>
                  <TableCell>Cloud consumer per Tenant</TableCell>
                  <TableCell>
                    <TextField
                      type="number"
                      value={formData.scale.consumers_per_tenant}
                      onChange={(e) => handleInputChange('consumers_per_tenant', e.target.value)}
                      size="small"
                      inputProps={{ min: 1 }}
                    />
                  </TableCell>
                </TableRow>
                <TableRow>
                  <TableCell>2</TableCell>
                  <TableCell>Total Tenant</TableCell>
                  <TableCell>
                    <TextField
                      type="number"
                      value={formData.scale.total_tenants}
                      onChange={(e) => handleInputChange('total_tenants', e.target.value)}
                      size="small"
                      inputProps={{ min: 1 }}
                    />
                  </TableCell>
                </TableRow>
                <TableRow>
                  <TableCell>3</TableCell>
                  <TableCell>Total End-points per Tenant</TableCell>
                  <TableCell>
                    <TextField
                      type="number"
                      value={formData.scale.endpoints_per_tenant}
                      onChange={(e) => handleInputChange('endpoints_per_tenant', e.target.value)}
                      size="small"
                      inputProps={{ min: 1 }}
                    />
                  </TableCell>
                </TableRow>
              </TableBody>
            </Table>
          </TableContainer>

          <Button
            variant="contained"
            color="primary"
            size="large"
            onClick={calculateCosts}
            sx={{ mt: 2 }}
          >
            Calculate Costs
          </Button>
        </Box>

        {costBreakdown && (
          <Box sx={{ mt: 4 }}>
            <Typography variant="h5" gutterBottom>Cost Breakdown (Monthly)</Typography>
            <Grid container spacing={3}>
              <Grid item xs={12} md={6}>
                <Paper elevation={2} sx={{ p: 2 }}>
                  <Typography variant="subtitle1">PxGrid Costs</Typography>
                  <Typography variant="h6">{formatCurrency(costBreakdown.breakdown.pxgrid_cost)}</Typography>
                </Paper>
              </Grid>
              <Grid item xs={12} md={6}>
                <Paper elevation={2} sx={{ p: 2 }}>
                  <Typography variant="subtitle1">Storage Costs</Typography>
                  <Typography variant="body2">DynamoDB: {formatCurrency(costBreakdown.breakdown.storage.dynamodb_cost)}</Typography>
                  <Typography variant="body2">S3: {formatCurrency(costBreakdown.breakdown.storage.s3_cost)}</Typography>
                </Paper>
              </Grid>
              <Grid item xs={12} md={6}>
                <Paper elevation={2} sx={{ p: 2 }}>
                  <Typography variant="subtitle1">Container Costs</Typography>
                  <Typography variant="h6">{formatCurrency(costBreakdown.breakdown.container_cost)}</Typography>
                </Paper>
              </Grid>
              <Grid item xs={12} md={6}>
                <Paper elevation={2} sx={{ p: 2 }}>
                  <Typography variant="subtitle1">Network Costs</Typography>
                  <Typography variant="body2">Throughput: {formatCurrency(costBreakdown.breakdown.network.throughput_cost)}</Typography>
                  <Typography variant="body2">MSK: {formatCurrency(costBreakdown.breakdown.network.msk_cost)}</Typography>
                </Paper>
              </Grid>
              <Grid item xs={12}>
                <Paper elevation={3} sx={{ p: 2, bgcolor: 'primary.light', color: 'primary.contrastText' }}>
                  <Typography variant="h6">Total Monthly Cost: {formatCurrency(costBreakdown.total_cost)}</Typography>
                  <Typography variant="subtitle1">Cost per Tenant: {formatCurrency(costBreakdown.monthly_cost_per_tenant)}</Typography>
                </Paper>
              </Grid>
            </Grid>
          </Box>
        )}

        <Snackbar
          open={notification.open}
          autoHideDuration={6000}
          onClose={handleCloseNotification}
        >
          <Alert onClose={handleCloseNotification} severity={notification.severity}>
            {notification.message}
          </Alert>
        </Snackbar>
      </Paper>
    </Container>
  );
}

export default CostCalculator;
